import Foundation
import XCTest
@testable import ScionicMerkleTree

/// The cross-language fastcdc-v1 conformance assertions.
///
/// The manifest — boundary offsets, chunk digests, edit-reuse partitions,
/// DAG roots and the root chunking tag for 11 cases — is generated by the Go
/// repo's `tools/fastcdcvectors` and COMMITTED here under
/// `spec/fastcdc-vectors` (manifest.json + manifest.cbor). Inputs are never
/// committed: every case regenerates deterministically from seeds, so the
/// corpus is pure expectation. Go, Swift and Rust all assert against the
/// same manifest. A missing manifest fails hard; it never skips.
///
/// The manifest is deliberately read from its CBOR form through this port's
/// own decoder — the JSON sibling exercises other parsers elsewhere, and a
/// harness that used a std-library JSON path here would leave the CBOR
/// decoder untested against fxamacker output carrying booleans.
final class FastCDCVectorTests: XCTestCase {

    // MARK: - Manifest Loading

    private struct ManifestMissing: Error, CustomStringConvertible {
        let path: String
        var description: String {
            """
            fastcdc-v1 vector manifest missing at \(path).
            It is committed to this repository; regenerate it from the Go repo with:
              go run ./tools/fastcdcvectors
            then copy spec/fastcdc-vectors/manifest.{json,cbor} into this repository.
            """
        }
    }

    private struct BadManifest: Error, CustomStringConvertible {
        let detail: String
        var description: String { "malformed fastcdc-v1 vector manifest: \(detail)" }
    }

    /// #filePath = <swift repo>/tests/tests/FastCDCVectorTests.swift
    private static let vectorsRoot: String = {
        let repoRoot = (((#filePath as NSString)
            .deletingLastPathComponent as NSString)
            .deletingLastPathComponent as NSString)
            .deletingLastPathComponent
        return (repoRoot as NSString).appendingPathComponent("spec/fastcdc-vectors")
    }()

    private func loadedManifest() throws -> [CBOROrderedMap] {
        let manifestPath = (Self.vectorsRoot as NSString).appendingPathComponent("manifest.cbor")
        guard FileManager.default.fileExists(atPath: manifestPath) else {
            throw ManifestMissing(path: manifestPath)
        }
        let data = try Data(contentsOf: URL(fileURLWithPath: manifestPath))
        let decoded = try CBORDecoder().decode(data)
        guard let top = decoded.mapValue else {
            throw BadManifest(detail: "top level is not a map")
        }
        guard top["spec"]?.stringValue == "fastcdc-v1" else {
            let found = top["spec"]
            throw BadManifest(detail: "spec gate mismatch: \(String(describing: found))")
        }
        guard let cases = top["cases"]?.arrayValue, !cases.isEmpty else {
            throw BadManifest(detail: "manifest lists no cases; every assertion would pass vacuously")
        }
        return try cases.map { value in
            guard let map = value.mapValue else {
                throw BadManifest(detail: "case entry is not a map")
            }
            return map
        }
    }

    // MARK: - Field Helpers (cbor omitempty: an absent key means zero/none)

    private func text(_ map: CBOROrderedMap, _ key: String) throws -> String {
        guard let value = map[key]?.stringValue else {
            throw BadManifest(detail: "missing text field '\(key)'")
        }
        return value
    }

    private func number(_ map: CBOROrderedMap, _ key: String) throws -> Int {
        guard let value = map[key]?.intValue else {
            throw BadManifest(detail: "missing numeric field '\(key)'")
        }
        return value
    }

    private func optionalNumber(_ map: CBOROrderedMap, _ key: String) -> Int {
        map[key]?.intValue ?? 0
    }

    private func items(_ map: CBOROrderedMap, _ key: String) throws -> [CBORValue] {
        guard let value = map[key]?.arrayValue else {
            throw BadManifest(detail: "missing array field '\(key)'")
        }
        return value
    }

    private func booleans(_ map: CBOROrderedMap, _ key: String) throws -> [Bool] {
        try items(map, key).map { value in
            guard case .bool(let flag) = value else {
                throw BadManifest(detail: "non-boolean entry in '\(key)'")
            }
            return flag
        }
    }

    private func hex(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }

    // MARK: - Case Materialization (normative generators)

    /// Block k of the stream is SHA-256(seed ++ u64be(k)); blocks are
    /// concatenated and truncated to `length`.
    private func corpusBytes(_ seed: String, _ length: Int) -> Data {
        var out = Data(capacity: length + 32)
        var block: UInt64 = 0
        while out.count < length {
            var message = Data(seed.utf8)
            withUnsafeBytes(of: block.bigEndian) { message.append(contentsOf: $0) }
            out.append(sha256Digest(message))
            block += 1
        }
        out.removeSubrange(length..<out.count)
        return out
    }

    private func caseByName(_ cases: [CBOROrderedMap], _ name: String) throws -> CBOROrderedMap {
        for candidate in cases where (try? text(candidate, "name")) == name {
            return candidate
        }
        throw BadManifest(detail: "edit case references unknown base case '\(name)'")
    }

    private func materialize(_ vectorCase: CBOROrderedMap, in cases: [CBOROrderedMap]) throws -> Data {
        let kind = try text(vectorCase, "kind")
        let length = try number(vectorCase, "length")
        switch kind {
        case "corpus":
            return corpusBytes(try text(vectorCase, "seed"), length)
        case "zeros":
            return Data(repeating: 0, count: length)
        case "edit":
            let base = try materialize(try caseByName(cases, try text(vectorCase, "base")), in: cases)
            let offset = optionalNumber(vectorCase, "offset")
            let editLength = try number(vectorCase, "edit_length")
            switch try text(vectorCase, "op") {
            case "insert":
                let payload = corpusBytes(try text(vectorCase, "payload_seed"), editLength)
                var edited = Data(capacity: base.count + payload.count)
                edited.append(base.subdata(in: 0..<offset))
                edited.append(payload)
                edited.append(base.subdata(in: offset..<base.count))
                return edited
            case "delete":
                var edited = Data(capacity: base.count - editLength)
                edited.append(base.subdata(in: 0..<offset))
                edited.append(base.subdata(in: (offset + editLength)..<base.count))
                return edited
            case let op:
                throw BadManifest(detail: "unknown edit op '\(op)'")
            }
        case let kind:
            throw BadManifest(detail: "unknown case kind '\(kind)'")
        }
    }

    // MARK: - Conformance Assertions

    func testVectorChunksMatch() throws {
        XCTAssertTrue(fastCDCEnabled(), "fastcdc-v1 must be the default mode")
        let cases = try loadedManifest()
        for vectorCase in cases {
            let name = try text(vectorCase, "name")
            let data = try materialize(vectorCase, in: cases)
            XCTAssertEqual(data.count, try number(vectorCase, "length"), "\(name): materialized length")
            let chunks = cutChunks(data)
            var ends: [Int] = []
            var offset = 0
            for chunk in chunks {
                offset += chunk.count
                ends.append(offset)
            }
            let expectedEnds = try items(vectorCase, "boundaries").map { value -> Int in
                guard let end = value.intValue else {
                    throw BadManifest(detail: "\(name): non-numeric boundary")
                }
                return end
            }
            XCTAssertEqual(ends, expectedEnds, "\(name): chunk end offsets")
            let expectedDigests = try items(vectorCase, "chunk_sha256").map { value -> String in
                guard let digest = value.stringValue else {
                    throw BadManifest(detail: "\(name): non-text chunk digest")
                }
                return digest
            }
            XCTAssertEqual(
                chunks.map { hex(sha256Digest($0)) }, expectedDigests,
                "\(name): chunk digests"
            )
        }
    }

    func testVectorEditReusePartitions() throws {
        let cases = try loadedManifest()
        var sawEditCase = false
        for vectorCase in cases {
            guard try text(vectorCase, "kind") == "edit" else { continue }
            sawEditCase = true
            let name = try text(vectorCase, "name")
            let base = try materialize(try caseByName(cases, try text(vectorCase, "base")), in: cases)
            let baseHashes = Set(cutChunks(base).map { sha256Digest($0) })
            let edited = try materialize(vectorCase, in: cases)
            let editedChunks = cutChunks(edited)
            let reused = editedChunks.map { baseHashes.contains(sha256Digest($0)) }
            XCTAssertEqual(reused, try booleans(vectorCase, "reused"), "\(name): reuse partition")
            let fresh = reused.filter { !$0 }.count
            XCTAssertTrue(
                (1...4).contains(fresh),
                "\(name): \(fresh) fresh chunks; an edit should stay confined to a few chunks"
            )
        }
        XCTAssertTrue(sawEditCase, "the manifest carries no edit cases; reuse went untested")
    }

    func testVectorDagRootsRebuild() throws {
        XCTAssertTrue(fastCDCEnabled(), "fastcdc-v1 must be the default mode")
        let cases = try loadedManifest()
        let tmpDir = try ParityTestHelpers.makeTempDir("fastcdc_vectors")
        defer { try? FileManager.default.removeItem(atPath: tmpDir) }
        for vectorCase in cases {
            let name = try text(vectorCase, "name")
            let data = try materialize(vectorCase, in: cases)
            let filePath = ParityTestHelpers.join(tmpDir, "\(name).bin")
            try ParityTestHelpers.writeData(filePath, data)

            let dag = try ScionicMerkleTree.createDag(path: filePath, timestampRoot: false)
            XCTAssertEqual(dag.root, try text(vectorCase, "root_hash"), "\(name): root CID")
            XCTAssertEqual(dag.leafs.count, try number(vectorCase, "leaf_count"), "\(name): leaf count")
            let chunkLeaves = dag.leafs.values.filter { $0.type == .chunk }.count
            XCTAssertEqual(chunkLeaves, try number(vectorCase, "chunk_leaves"), "\(name): chunk leaves")
            if try items(vectorCase, "boundaries").count <= 1 {
                XCTAssertEqual(chunkLeaves, 0, "\(name): single-chunk content stores inline, no chunk leaves")
            }
            let rootLeaf = try XCTUnwrap(dag.leafs[dag.root], name)
            XCTAssertEqual(
                rootLeaf.additionalData[chunkingTagKey], chunkingFastCDCV1,
                "\(name): fastcdc roots carry the chunking tag"
            )
            try dag.verify()
        }
    }

    // MARK: - Root-Tag Semantics

    func testRootTagSemantics() throws {
        defer { setDefaultChunkSize() }
        let root = try ParityTestHelpers.makeTempDir("fastcdc_root_tag")
        defer { try? FileManager.default.removeItem(atPath: root) }
        try ParityTestHelpers.write(ParityTestHelpers.join(root, "file.txt"), "tag semantics")

        // Default mode stamps exactly the chunking tag.
        setDefaultChunkSize()
        let plain = try ScionicMerkleTree.createDag(path: root, timestampRoot: false)
        let plainRoot = try XCTUnwrap(plain.leafs[plain.root])
        XCTAssertEqual(plainRoot.additionalData, [chunkingTagKey: chunkingFastCDCV1])
        try plain.verify()

        // The library owns the key: a caller-supplied value is overwritten,
        // and other caller keys survive.
        let overridden = try createDagAdvanced(
            path: root,
            additionalData: [chunkingTagKey: "wrong", "keep": "x"]
        )
        let overriddenRoot = try XCTUnwrap(overridden.leafs[overridden.root])
        XCTAssertEqual(
            overriddenRoot.additionalData,
            [chunkingTagKey: chunkingFastCDCV1, "keep": "x"]
        )
        try overridden.verify()

        // The parallel constructor funnels through the same stamp.
        let parallel = try createDagWithConfig(path: root, config: DagBuilderConfig.parallelConfig())
        let parallelRoot = try XCTUnwrap(parallel.leafs[parallel.root])
        XCTAssertEqual(parallelRoot.additionalData, [chunkingTagKey: chunkingFastCDCV1])
        XCTAssertEqual(parallel.root, plain.root, "parallel and sequential builds must agree")

        // A timestamped fastcdc root carries exactly {timestamp, chunking} —
        // the tag is stamped AFTER the timestamp map is built, matching Go's
        // order. Root metadata is hashed into the root CID, so the stamping
        // order itself is cross-language normative.
        let timestamped = try ScionicMerkleTree.createDag(path: root, timestampRoot: true)
        let timestampedRoot = try XCTUnwrap(timestamped.leafs[timestamped.root])
        XCTAssertEqual(timestampedRoot.additionalData.count, 2)
        XCTAssertEqual(timestampedRoot.additionalData[chunkingTagKey], chunkingFastCDCV1)
        XCTAssertNotNil(timestampedRoot.additionalData["timestamp"])
        try timestamped.verify()

        // Legacy modes stamp nothing: absent tag ⇒ fixed-2m.
        setChunkSize(4096)
        let legacy = try ScionicMerkleTree.createDag(path: root, timestampRoot: false)
        let legacyRoot = try XCTUnwrap(legacy.leafs[legacy.root])
        XCTAssertTrue(legacyRoot.additionalData.isEmpty)
        try legacy.verify()

        let legacyAdvanced = try createDagAdvanced(path: root, additionalData: ["keep": "x"])
        let legacyAdvancedRoot = try XCTUnwrap(legacyAdvanced.leafs[legacyAdvanced.root])
        XCTAssertEqual(legacyAdvancedRoot.additionalData, ["keep": "x"])
        try legacyAdvanced.verify()
    }
}
